<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$result=mysqli_query($koneksi,"SELECT ps.*,f.nama_fakultas,(SELECT COUNT(*) FROM mahasiswa m WHERE m.id_program_studi=ps.id_program_studi) jumlah_mahasiswa FROM program_studi ps JOIN fakultas f ON ps.id_fakultas=f.id_fakultas ORDER BY ps.id_program_studi DESC");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Program Studi</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading page-heading-flex"><div><span class="eyebrow">MASTER DATA</span><h1>Program Studi</h1><p>Kelola daftar program studi.</p></div><a class="btn btn-primary" href="prodi_tambah.php">+ Tambah Program Studi</a></div><?php flash_html();?><div class="dashboard-panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>No</th><th>Kode</th><th>Program Studi</th><th>Fakultas</th><th>Jenjang</th><th>Status</th><th>Mahasiswa</th><th>Aksi</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($result)):?><tr><td><?=$no++?></td><td><span class="badge"><?=e($r['kode_program_studi'])?></span></td><td><strong><?=e($r['nama_program_studi'])?></strong></td><td><?=e($r['nama_fakultas'])?></td><td><?=e($r['jenjang'])?></td><td><span class="badge <?= $r['status_aktif']==='Aktif'?'':'badge-warning'?>"><?=e($r['status_aktif'])?></span></td><td><?=$r['jumlah_mahasiswa']?></td><td><div class="action-group"><a class="btn btn-sm btn-outline" href="prodi_edit.php?id=<?=$r['id_program_studi']?>">Edit</a><form method="post" action="prodi_hapus.php" onsubmit="return confirm('Hapus program studi ini?');"><input type="hidden" name="id" value="<?=$r['id_program_studi']?>"><?=csrf_field()?><button class="btn btn-sm btn-danger">Hapus</button></form></div></td></tr><?php endwhile;?></tbody></table></div></div></main><script src="script.js"></script></body></html>